1	package com.loja.checkout;
2	
3	import com.loja.checkout.api.PedidoRequest;
4	import com.loja.checkout.api.ResumoResponse;
5	import com.loja.checkout.clube.NivelClube;
6	import com.loja.checkout.cupom.ContextoCupom;
7	import com.loja.checkout.cupom.Cupom;
8	import com.loja.checkout.entrega.ModalidadeEntrega;
9	import com.loja.checkout.pagamento.FormaPagamento;
10	import com.loja.checkout.pagamento.Pagamento;
11	import java.math.BigDecimal;
12	import java.util.List;
13	import java.util.Optional;
14	import org.springframework.stereotype.Service;
15	
16	/** Ordem fixa do cálculo e das validações; o que varia fica nos casos de cada catálogo. */
17	@Service
18	public class CalculadoraResumo {
19	
20	    private final Catalogo<ModalidadeEntrega> modalidades;
21	    private final Catalogo<Cupom> cupons;
22	    private final Catalogo<NivelClube> niveis;
23	    private final Catalogo<FormaPagamento> formasPagamento;
24	
25	    public CalculadoraResumo(Catalogo<ModalidadeEntrega> modalidades, Catalogo<Cupom> cupons,
26	            Catalogo<NivelClube> niveis, Catalogo<FormaPagamento> formasPagamento) {
27	        this.modalidades = modalidades;
28	        this.cupons = cupons;
29	        this.niveis = niveis;
30	        this.formasPagamento = formasPagamento;
31	    }
32	
33	    public ResumoResponse calcular(PedidoRequest pedido) {
34	        Carrinho carrinho = carrinhoValido(pedido.itens());
35	        NivelClube nivel = exigir(niveis.buscar(pedido.nivelClube()), "NIVEL_CLUBE_INVALIDO");
36	        Regiao regiao = exigir(Regiao.buscar(pedido.regiao()), "REGIAO_INVALIDA");
37	        ModalidadeEntrega modalidade = exigir(modalidades.buscar(pedido.modalidadeEntrega()), "MODALIDADE_INVALIDA");
38	        verificar(modalidade.atende(carrinho), "MODALIDADE_INDISPONIVEL");
39	
40	        BigDecimal subtotal = carrinho.subtotal();
41	        BigDecimal frete = nivel.frete(modalidade.frete(carrinho));
42	        BigDecimal desconto = descontoCupom(pedido.cupom(), new ContextoCupom(carrinho, subtotal, frete));
43	        BigDecimal seguro = regiao.seguro(subtotal);
44	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
45	
46	        FormaPagamento forma = exigir(formasPagamento.buscar(pedido.formaPagamento()), "FORMA_PAGAMENTO_INVALIDA");
47	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
48	        verificar(forma.aceitaParcelas(parcelas), "PARCELAMENTO_INVALIDO");
49	        verificar(forma.disponivel(totalPedido), "FORMA_PAGAMENTO_INDISPONIVEL");
50	        Pagamento pagamento = forma.pagar(totalPedido, parcelas);
51	
52	        return new ResumoResponse(
53	                subtotal,
54	                desconto,
55	                frete,
56	                modalidade.prazoDias(),
57	                seguro,
58	                pagamento.totalFinal().subtract(totalPedido),
59	                pagamento.totalFinal(),
60	                pagamento.parcelas(),
61	                pagamento.valorParcela(),
62	                nivel.credito(subtotal),
63	                nivel.brinde(subtotal));
64	    }
65	
66	    private BigDecimal descontoCupom(String codigo, ContextoCupom contexto) {
67	        if (codigo == null) {
68	            return Dinheiro.ZERO;
69	        }
70	        Cupom cupom = exigir(cupons.buscar(codigo), "CUPOM_INVALIDO");
71	        verificar(cupom.aplicavel(contexto), "CUPOM_NAO_APLICAVEL");
72	        return cupom.desconto(contexto);
73	    }
74	
75	    private static Carrinho carrinhoValido(List<Item> itens) {
76	        verificar(itens != null && !itens.isEmpty(), "PEDIDO_INVALIDO");
77	        itens.forEach(item -> verificar(itemValido(item), "PEDIDO_INVALIDO"));
78	        return new Carrinho(itens);
79	    }
80	
81	    private static boolean itemValido(Item item) {
82	        return item != null
83	                && positivo(item.precoUnitario())
84	                && item.quantidade() != null && item.quantidade() > 0
85	                && positivo(item.pesoKg());
86	    }
87	
88	    private static boolean positivo(BigDecimal valor) {
89	        return valor != null && valor.signum() > 0;
90	    }
91	
92	    private static <T> T exigir(Optional<T> caso, String erro) {
93	        return caso.orElseThrow(() -> new CheckoutException(erro));
94	    }
95	
96	    private static void verificar(boolean condicao, String erro) {
97	        if (!condicao) {
98	            throw new CheckoutException(erro);
99	        }
100	    }
101	}
