3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	/** Arredondamento único de valores em dinheiro: centavos, meio para o par. */
7	public final class Dinheiro {
8	
9	    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);
10	
11	    private Dinheiro() {
12	    }
13	
14	    public static BigDecimal centavos(BigDecimal valor) {
15	        return valor.setScale(2, RoundingMode.HALF_EVEN);
16	    }
17	
18	    /** Percentual (ex.: 2.5 para 2,5%) sobre um valor, arredondado para centavos. */
19	    public static BigDecimal percentual(BigDecimal valor, String percentual) {
20	        return centavos(valor.multiply(new BigDecimal(percentual)).movePointLeft(2));
21	    }
22	}
