3	import java.util.List;
4	import java.util.Map;
5	import java.util.Optional;
6	import java.util.function.Function;
7	import java.util.stream.Collectors;
8	
9	/** Escolhe o caso pelo código: um mapa montado a partir das implementações registradas. */
10	public final class Catalogo<T extends Codificado> {
11	
12	    private final Map<String, T> porCodigo;
13	
14	    public Catalogo(List<T> casos) {
15	        this.porCodigo = casos.stream().collect(Collectors.toUnmodifiableMap(Codificado::codigo, Function.identity()));
16	    }
17	
18	    public Optional<T> buscar(String codigo) {
19	        return codigo == null ? Optional.empty() : Optional.ofNullable(porCodigo.get(codigo));
20	    }
21	}
