1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	class Cartao implements FormaPagamento {
10	
11	    private static final int MAXIMO_PARCELAS = 12;
12	    private static final int MAXIMO_SEM_JUROS = 3;
13	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
14	
15	    @Override
16	    public String codigo() {
17	        return "CARTAO";
18	    }
19	
20	    @Override
21	    public boolean aceitaParcelas(int parcelas) {
22	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
23	    }
24	
25	    @Override
26	    public Pagamento pagar(BigDecimal totalPedido, int parcelas) {
27	        if (parcelas <= MAXIMO_SEM_JUROS) {
28	            BigDecimal parcela = Dinheiro.centavos(totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128));
29	            return new Pagamento(totalPedido, parcelas, parcela);
30	        }
31	        BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
32	        return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcelas, parcela);
33	    }
34	
35	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
36	    private static BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
37	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
38	        BigDecimal descontado = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
39	        return total.multiply(TAXA_MENSAL).divide(descontado, MathContext.DECIMAL128);
40	    }
41	}
